const pageSize=100,actionNames={login:"Login",login_failed:"Failed login",logout:"Logout",password_changed:"Password changed","2fa_enabled":"Two-factor turned on","2fa_disabled":"Two-factor turned off",recovery_codes_regenerated:"Recovery codes regenerated",impersonate:"Impersonation",api_request:"Change",api_request_failed:"Failed change",api_request_denied:"Denied change"};let oldestId=0;const load=i=>{let t={limit:100,username:$("#audit_username").val(),action:$("#audit_action").val()};i?t.before_id=oldestId:($("#auditTable tbody").empty(),$("#auditTable").hide(),$("#loading").show()),api.auditLog.get(t).success(d=>{$("#loading").hide(),$("#auditTable").show(),$.each(d,(o,e)=>{oldestId=e.id;let a=$("<tr>");a.append($("<td>").text(moment(e.created_at).format("MMMM Do YYYY, h:mm:ss a"))),a.append($("<td>").text(e.username)),a.append($("<td>").text(actionNames[e.action]||e.action)),a.append($("<td>").text(e.target)),a.append($("<td>").text(e.details)),a.append($("<td>").text(e.ip_address)),$("#auditTable tbody").append(a)}),$("#auditOlder").toggleClass("hidden",d.length<100)}).error(()=>{$("#loading").hide(),errorFlash("Error fetching the audit log")})};$(document).ready(function(){load(!1),$("#auditFilterForm").submit(function(){return load(!1),!1}),$("#auditOlder").click(function(){load(!0)})});
